CREATE TABLE IF NOT EXISTS cita(id UUID PRIMARY KEY,paciente_id UUID NOT NULL,especialidad VARCHAR(80) NOT NULL,fecha_hora TIMESTAMP WITH TIME ZONE NOT NULL,profesional_codigo VARCHAR(50) NOT NULL,motivo VARCHAR(200) NOT NULL,estado VARCHAR(15) NOT NULL CHECK(estado IN ('PENDIENTE','CONFIRMADA','ATENDIDA','CANCELADA','AUSENTE')),fecha_creacion TIMESTAMP WITH TIME ZONE NOT NULL,fecha_actualizacion TIMESTAMP WITH TIME ZONE NOT NULL,version INTEGER NOT NULL,atencion_id UUID);
CREATE UNIQUE INDEX IF NOT EXISTS cita_agenda_profesional ON cita(profesional_codigo,fecha_hora) WHERE estado NOT IN ('CANCELADA','AUSENTE');
CREATE UNIQUE INDEX IF NOT EXISTS cita_agenda_paciente ON cita(paciente_id,fecha_hora) WHERE estado NOT IN ('CANCELADA','AUSENTE');
CREATE TABLE IF NOT EXISTS historial_cita(id UUID PRIMARY KEY,cita_id UUID NOT NULL REFERENCES cita(id),estado_anterior VARCHAR(15),estado_nuevo VARCHAR(15) NOT NULL,fecha TIMESTAMP WITH TIME ZONE NOT NULL,origen VARCHAR(50) NOT NULL,detalle VARCHAR(350));
CREATE TABLE IF NOT EXISTS outbox(event_id UUID PRIMARY KEY,routing_key VARCHAR(100) NOT NULL,payload TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,sent_at TIMESTAMP WITH TIME ZONE);
CREATE INDEX IF NOT EXISTS outbox_pendiente ON outbox(created_at) WHERE sent_at IS NULL;
